function findProvinsi(kodeProv) {
  return WILAYAH_DATA.find(p => p.kode === kodeProv);
}

function findKabupaten(kodeProv, kodeKab) {
  const prov = findProvinsi(kodeProv);
  return prov ? prov.kabupaten.find(k => k.kode === kodeKab) : null;
}

function findKecamatan(kodeProv, kodeKab, kodeKec) {
  const kab = findKabupaten(kodeProv, kodeKab);
  return kab ? kab.kecamatan.find(k => k.kode === kodeKec) : null;
}

function findDesa(kodeProv, kodeKab, kodeKec, kodeDesa) {
  const kec = findKecamatan(kodeProv, kodeKab, kodeKec);
  return kec ? kec.desa.find(d => d.kode === kodeDesa) : null;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { WILAYAH_DATA, findProvinsi, findKabupaten, findKecamatan, findDesa };
}
